+@page "/shipments/{TrackingNumber}"
+@rendermode InteractiveAuto
+@using sv_b61764e8f61c4aa9b6a4d2be680ad2c0.Client.Models
+@using sv_b61764e8f61c4aa9b6a4d2be680ad2c0.Client.Services
+@inject IShipmentService ShipmentService
+@inject ILogger<ShipmentTracker> Logger
+@implements IDisposable
+
+<PageTitle>Shipment @TrackingNumber</PageTitle>
+
+<h2>Shipment Tracking</h2>
+
+@if (_loading)
+{
+    <div class="alert alert-info" role="status">
+        <em>Loading shipment details for @TrackingNumber&hellip;</em>
+    </div>
+}
+else if (_errorMessage is not null)
+{
+    <div class="alert alert-danger" role="alert">
+        <p>@_errorMessage</p>
+        <button class="btn btn-outline-danger" @onclick="RetryAsync">Retry</button>
+    </div>
+}
+else if (_shipment is null)
+{
+    <div class="alert alert-warning">
+        No shipment found for tracking number <strong>@TrackingNumber</strong>.
+    </div>
+}
+else
+{
+    <div>
+        <dl>
+            <dt>Tracking Number</dt>
+            <dd>@_shipment.TrackingNumber</dd>
+
+            <dt>Status</dt>
+            <dd>@_shipment.Status</dd>
+
+            <dt>Location</dt>
+            <dd>@_shipment.Location</dd>
+
+            <dt>Estimated Delivery</dt>
+            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
+        </dl>
+
+        <h4>Status History</h4>
+
+        @if (_shipment.StatusUpdates.Count == 0)
+        {
+            <p>No status updates yet.</p>
+        }
+        else
+        {
+            <table class="table table-striped">
+                <thead>
+                    <tr>
+                        <th>Time</th>
+                        <th>Description</th>
+                    </tr>
+                </thead>
+                <tbody>
+                    @foreach (var update in _shipment.StatusUpdates)
+                    {
+                        <tr>
+                            <td>@update.Timestamp.ToString("g")</td>
+                            <td>@update.Description</td>
+                        </tr>
+                    }
+                </tbody>
+            </table>
+        }
+    </div>
+}
+
+@code {
+    [Parameter]
+    public string TrackingNumber { get; set; } = string.Empty;
+
+    private Shipment? _shipment;
+    private bool _loading;
+    private string? _errorMessage;
+
+    private CancellationTokenSource _cts = new();
+
+    protected override Task OnParametersSetAsync() => LoadShipmentAsync();
+
+    private async Task LoadShipmentAsync()
+    {
+        // Cancel any in-flight request (handles route-parameter changes).
+        await CancelPendingRequestAsync();
+
+        var cts = _cts = new CancellationTokenSource();
+
+        _loading = true;
+        _errorMessage = null;
+        _shipment = null;
+
+        try
+        {
+            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, cts.Token);
+        }
+        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
+        {
+            // Navigation away or dispose — silently abandon.
+            return;
+        }
+        catch (TimeoutException ex)
+        {
+            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
+            _errorMessage = "The request timed out. Please try again.";
+        }
+        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
+        {
+            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
+            _errorMessage = "The request timed out. Please try again.";
+        }
+        catch (Exception ex)
+        {
+            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
+            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private Task RetryAsync() => LoadShipmentAsync();
+
+    private async ValueTask CancelPendingRequestAsync()
+    {
+        var old = _cts;
+        await old.CancelAsync();
+        old.Dispose();
+    }
+
+    public void Dispose()
+    {
+        _cts.Cancel();
+        _cts.Dispose();
+    }
+}
+

